<?php require_once __DIR__.'/include/config.php';require_once __DIR__.'/include/clinical.php';hms_start_session();$role=(string)($_SESSION['role']??'');if(!in_array($role,['patient','doctor','admin'],true)){http_response_code(403);exit('Sign in required.');}hms_require_role($role);$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;if(!hms_stage6_ready($con)){http_response_code(503);exit(hms_clinical_notice());}$sql='SELECT h.*,u.fullName patient,d.doctorName FROM prescription_headers h JOIN users u ON u.id=h.patient_user_id JOIN doctors d ON d.id=h.doctor_id WHERE h.id=?';$params=[$id];if($role==='patient'){$sql.=' AND h.patient_user_id=?';$params[]=(int)$_SESSION['id'];}if($role==='doctor'){$sql.=' AND h.doctor_id=?';$params[]=(int)$_SESSION['id'];}$header=hms_db_query($con,$sql,$params)->fetch_assoc();if(!$header){http_response_code(404);exit('Prescription not found.');}$items=hms_db_query($con,'SELECT * FROM prescription_items WHERE prescription_id=?',[$id]);?>
<!doctype html><html><head><meta charset="utf-8"><title>Prescription #<?=hms_h($id)?></title><link rel="stylesheet" href="vendor/bootstrap/css/bootstrap.min.css"><style>@media print{button,a{display:none}}.rx{max-width:800px;margin:35px auto}</style></head><body><main class="rx"><a href="javascript:history.back()">Back</a> <button onclick="window.print()" class="btn btn-primary pull-right">Print</button><h1>MedTech Hospital</h1><h2>Prescription</h2><p><b>Patient:</b> <?=hms_h($header['patient'])?><br><b>Doctor:</b> <?=hms_h($header['doctorName'])?><br><b>Issued:</b> <?=hms_h($header['issue_date'])?></p><?php if($header['clinical_notes']):?><p><?=nl2br(hms_h($header['clinical_notes']))?></p><?php endif;?><table class="table table-bordered"><tr><th>Medicine</th><th>Dosage</th><th>Frequency</th><th>Duration</th><th>Instructions</th></tr><?php while($i=$items->fetch_assoc()):?><tr><td><?=hms_h($i['medicine_name'])?></td><td><?=hms_h($i['dosage'])?></td><td><?=hms_h($i['frequency'])?></td><td><?=hms_h($i['duration'])?></td><td><?=hms_h($i['instructions'])?></td></tr><?php endwhile;?></table></main></body></html>
